using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class AudienceActualChecks {
 public sealed class Baseline {public Video video;public string[] comments;public string status,copied_at;}
 sealed class Progress:System.IProgress<DualCommentResult>{string prior;public void Report(DualCommentResult r){if(r.ActiveModel!=prior){prior=r.ActiveModel;Console.WriteLine("PHASE "+prior+" candidates="+r.Count);}}}
 public static int Main(string[] a){try{string root=a[0],dir=Path.Combine(root,"extension/data/replier-grounded-checks");var json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};var before=json.Deserialize<Baseline>(File.ReadAllText(Path.Combine(dir,"audience-baseline-dIRksYUQz6Y.json")));var content=new ContentStore(Path.Combine(root,"extension/data/replier/content")).Load(before.video.Id);var watch=Stopwatch.StartNew();DualCommentResult after;
 using(var service=new DualCommentService(Path.Combine(root,"extension/.runtime/replier-llm"),false)){after=service.Generate(before.video,content,CancellationToken.None,true,new Progress()).GetAwaiter().GetResult();}
 var all=after.Batches.Where(b=>b.Result!=null).SelectMany(b=>b.Result.Comments).ToArray();var ranked=all.Where(c=>c.FitEligible==true).OrderByDescending(c=>c.TiePreference).ThenByDescending(c=>c.FitScore).ToArray();var best=ranked.FirstOrDefault();bool usesReference=after.Batches.Any(b=>b.Result!=null&&b.Result.ReferenceComments!=null&&b.Result.ReferenceComments.Length>0&&!string.IsNullOrEmpty(b.Result.ReactionGuide));bool noCopy=all.All(c=>!AudienceComments.Copies(c.Text,after.Batches.Where(b=>b.Result!=null).SelectMany(b=>b.Result.ReferenceComments??new string[0])));bool pass=after.Batches.Count==2&&after.Batches.All(b=>b.Result!=null&&string.IsNullOrEmpty(b.Error))&&after.Complete&&!after.Cancelled&&best!=null&&usesReference&&noCopy;
 File.WriteAllText(Path.Combine(dir,"audience-condition-grounded-dIRksYUQz6Y.json"),json.Serialize(new{before=before,after=after,best=best,seconds=watch.Elapsed.TotalSeconds,pass=pass,used_actual_public_comments=usesReference,no_near_copies=noCopy,automatic_quality_regeneration=false}));File.WriteAllText(Path.Combine(dir,"audience-condition-grounded-debug-dIRksYUQz6Y.txt"),CommentDebugReport.Format(before.video,after,best,"댓글 참고 방식 비교",""));
 Console.WriteLine("FINAL complete="+after.Complete+" count="+all.Length+" passed="+ranked.Length+" error="+after.ScoreError+" seconds="+watch.Elapsed.TotalSeconds.ToString("F1"));foreach(var b in after.Batches){Console.WriteLine(b.Label+" "+b.Error);if(b.Result!=null){Console.WriteLine(b.Result.ReferenceStatus);Console.WriteLine(b.Result.ReactionGuide);foreach(var c in b.Result.Comments)Console.WriteLine(c.FitScore+" | "+c.Text+" | "+c.FitError);}}Console.WriteLine(pass?"PASS public-comment-assisted production generation":"FAIL inspect saved comparison");return pass?0:1;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
